#!/usr/bin/env python3
"""Generate the complete VOID RUNNER game as index.html"""
lines = []
def W(s=""):
    lines.append(s)

# HTML start
W('<!DOCTYPE html>')
W('<html lang="en">')
W('<head>')
W('<meta charset="UTF-8">')
W('<meta name="viewport" content="width=device-width, initial-scale=1.0">')
W('<title>VOID RUNNER</title>')
W('<style>')
W('''* { margin:0; padding:0; box-sizing:border-box }
html,body { width:100%; height:100%; overflow:hidden; background:#0a0a12; font-family:'Courier New',monospace; user-select:none; cursor:crosshair }
#gw { position:relative; width:100%; height:100%; display:flex; align-items:center; justify-content:center }
#c { image-rendering:pixelated; pointer-events:none }
#co { position:absolute; top:0; left:0; width:100%; height:100%; pointer-events:none; z-index:10 }
.sl { position:absolute; top:0; left:0; width:100%; height:100%; background:repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,0,0,0.08) 2px,rgba(0,0,0,0.08) 4px) }
.vg { position:absolute; top:0; left:0; width:100%; height:100%; background:radial-gradient(ellipse at center,transparent 40%,rgba(0,0,0,0.6) 100%) }
#uo { position:absolute; top:0; left:0; width:100%; height:100%; z-index:20; display:flex; align-items:center; justify-content:center }
#uo * { pointer-events:auto }''')
W('''#dm { display:none; position:absolute; bottom:20px;left:20px;background:rgba(0,0,0,0.92);border:1px solid #0fa;color:#0fa;padding:15px;font-size:13px;z-index:100;pointer-events:auto;max-width:360px;font-family:'Courier New',monospace }
#dm h3 { margin-bottom:6px;font-size:15px;color:#4ff }
.dmb { display:block;width:100%;margin:3px 0;padding:5px 10px;background:transparent;border:1px solid #0fa;color:#0fa;cursor:pointer;font-family:inherit;font-size:12px }
.dmb:hover { background:rgba(0,255,170,0.2) }
.dmi { background:#111;border:1px solid #0fa;color:#0fa;padding:3px;width:60px;font-family:inherit;font-size:12px }
.dms { background:#111;border:1px solid #0fa;color:#0fa;padding:3px;font-family:inherit;font-size:12px;width:100%;margin:2px 0 }
.dlr { display:flex;gap:5px;margin:4px 0;align-items:center }
''')
W('</style></head><body>')
W('<div id="gw"><canvas id="c"></canvas></div>')
W('<div id="co"><div class="sl"></div><div class="vg"></div></div>')
W('<div id="uo"></div>')

# Debug menu
W('<div id="dm">')
W('<h3>DEBUG (F2)</h3>')
W('<button class="dmb" onclick="dbCl()">Close</button>')
W('<div class="dlr"><label>Sector <input class="dmi" type="number" id="ds" value="1" min="1" max="30"></label><button class="dmb" onclick="dbGo()">Go</button></div>')
W('<div class="dlr"><label>Enemy<select class="dms" id="de"><option value="scout">Scout</option><option value="raider">Raider</option><option value="cruiser">Cruiser</option><option value="cannon">Cannon</option><option value="swarm">Swarm</option><option value="dreadnought">Dreadnought</option><option value="boss1">Boss 1</option><option value="boss2">Boss 2</option><option value="boss3">Boss 3</option></select></label><button class="dmb" onclick="dbSp()">Spawn</button></div>')
W('<div class="dlr"><label>Credits <input class="dmi" type="number" id="dc" value="100"></label><button class="dmb" onclick="dbAC()">Add</button></div>')
W('<br><label><input type="checkbox" id="di"> Invulnerable</label>')
W('<br><label><input type="checkbox" id="dg" checked> God Mode</label>')
W('<br><button class="dmb" onclick="dbCE()">Clear Enemies</button>')
W('<button class="dmb" onclick="dbCB()">Clear Projectiles</button>')
W('<button class="dmb" onclick="dbCP()">Clear Particles</button>')
W('<button class="dmb" onclick="dbCU()">Clear Powerups</button>')
W('</div>')
W('<script>')

# Now JavaScript - each line carefully
J = lines # append to lines as JS content
def JS(s=""):
    J.append(s)

JS('(function(){')
JS('"use strict";')
JS('var c=document.getElementById("c"),X=c.getContext("2d");')
JS('var CW=1280,CH=720;c.width=CW;c.height=CH;')
JS('function resize(){try{var s=Math.min(window.innerWidth/CW,window.innerHeight/CH);c.style.width=(CW*s)+"px";c.style.height=(CH*s)+"px"}catch(e){}}')
JS('setTimeout(resize,50);window.onresize=resize;')
JS('')

# Constants
JS('var MP=800,ME=14,MD=0.05;')
JS('var CCW=3,CXM=5,CBL=0.15;')
JS('var SCR={scout:100,swarmling:40,raider:200,cannon:300,cruiser:500,dreadnought:1000,boss:5000};')
JS('var HM=100;')
JS('')

# Themes
JS('var THEM=[null,')
JS('  {bg:"#1a0a2e",n1:"#3a1060",n2:"#25104a",bg:"#0d0520",ac:"#d050ff",nm:"Nebula Drift"},')
JS('  {bg:"#1e0c32",n1:"#481870",n2:"#2c1455",bg:"#0f0626",ac:"#d858ff",nm:"Nebula Drift"},')
JS('  {bg:"#220e38",n1:"#562080",n2:"#331760",bg:"#11082a",ac:"#e060ff",nm:"Nebula Drift"},')
JS('  {bg:"#281c14",n1:"#655020",n2:"#453515",bg:"#18140a",ac:"#d4a030",nm:"Asteroid Belt"},')
JS('  {bg:"#2c2018",n1:"#735e24",n2:"#4d3f19",bg:"#1c180c",ac:"#dca838",nm:"Asteroid Belt"},')
JS('  {bg:"#32261c",n1:"#806828",n2:"#58481d",bg:"#201a10",ac:"#e4b040",nm:"Asteroid Belt"},')
JS('  {bg:"#08162a",n1:"#183c60",n2:"#102640",bg:"#040e16",ac:"#40d0ff",nm:"Void Rift"},')
JS('  {bg:"#0c1a30",n1:"#1c4a72",n2:"#143250",bg:"#06121e",ac:"#48d8ff",nm:"Void Rift"},')
JS('  {bg:"#102036",n1:"#246080",n2:"#1a4058",bg:"#081828",ac:"#50e0ff",nm:"Void Rift"},')
JS('  {bg:"#1a0a18",n1:"#402040",n2:"#2a1528",bg:"#0e050e",ac:"#ff8000",nm:"Deep Void"}];')
JS('')

# Save/load
JS('var MT={starCharts:0,hullLv:0,shieldLv:0,shieldRlv:0,engineLv:0,mainLv:0,sideLv:0,spreadLv:0,heatLv:0,repairLv:0,heatBv:0,rail:false,crit:false,tank:false,speed:false,startCr:0,wDmg:0,maxHpExtra:0,shieldExtra:0};')
JS('var hsc=[];')
JS('function defM(){var o={};for(var k in MT)o[k]=MT[k];return o}')
JS('function loadSV(){try{var raw=localStorage.getItem("vr_v1");if(raw){var o=JSON.parse(raw);for(var k in MT)if(o[k]!==undefined&&o[k]!==null)MT[k]=o[k]};hsc=o.highscores||[]}catch(e){hsc=[]}if(MT.starCharts===undefined)MT=defM();if(!hsc||hsc.length===0)hsc=[]}')
JS('function saveSV(){try{var o={},k;for(k in MT)o[k]=MT[k];o.highscores=hsc;localStorage.setItem("vr_v1",JSON.stringify(o))}catch(e){}}')
JS('function rstSV(){try{localStorage.removeItem("vr_v1")}catch(e){}MT=defM();hsc=[];saveSV()}')
JS('function addSc(score,sector){hsc.push({score:score,date:new Date().toLocaleDateString(),sector:sector||1});hsc.sort(function(a,b){return b.score-a.score});while(hsc.length>10)hsc.pop();saveSV()}')
JS('loadSV();saveSV();')
JS('')

# Input
JS('var iK={},iM={x:CW/2,y:CH/2,dn:false},iA=0;')
JS('document.addEventListener("keydown",function(e){var kc=e.keyCode;if([32,37,38,39,40,33,34,36,35,45].indexOf(kc)>=0)e.preventDefault();iK[kc]=true;if(kc===27){if(cur==="combat"){cur="paused";bUI()}else if(cur==="paused"){cur="combat";bUI()}}if(kc===77&&aCtx){mute=!mute;if(mute)aCtx.suspend();else{try{aCtx.resume()}catch(ex){}}}})')
JS('document.addEventListener("keyup",function(e){iK[e.keyCode]=false;if([37,38,39,40,33,34,36,35,45].indexOf(e.keyCode)>=0)e.preventDefault()})')
JS('document.addEventListener("mousemove",function(e){var r=c.getBoundingClientRect();iM.x=(e.clientX-r.left)*(CW/r.width);iM.y=(e.clientY-r.top)*(CH/r.height);if(pl)iA=Math.atan2(iM.y-pl.y,iM.x-pl.x)})')
JS('document.addEventListener("mousedown",function(e){e.preventDefault();iM.dn=true;initA()})')
JS('document.addEventListener("mouseup",function(){iM.dn=false})')
JS('document.addEventListener("mouseleave",function(){iM.rem=true});document.addEventListener("mouseenter",function(){iM.rem=false})')
JS('')

# Audio
JS('var aCtx=null,mute=false,mG=null,aBuf={};')
JS('function initA(){if(aCtx)return;try{aCtx=new(window.AudioContext||window.webkitAudioContext)();mG=aCtx.createGain();mG.gain.value=0.25;mG.connect(aCtx.destination)}catch(ex){}}')
JS('function mkB(name){')
JS('  var buf,sr=aCtx.sampleRate,len=sr*0.12|1;buf=aCtx.createBuffer(1,len,sr);var d=buf.getChannelData(0);')
JS('  for(var i=0;i<len;i++){var t=i/sr,v=0,n=2*Math.random()-1;')
JS('    if(name==="shoot"){var f=700-n*150;v=(n*Math.exp(-t*45)*0.2+Math.sin(6.28*f*t)*0.1*Math.exp(-t*25))}')
JS('    else if(name==="hit"){v=Math.sin(300*t+n)*Math.exp(-t*15)*0.15}')
JS('    else if(name==="boom"){var lo=50-n*30;v=(n*0.4+Math.sin(6.28*lo*t)*0.2)*Math.exp(-t*6)}')
JS('    else if(name==="dash"){v=Math.sin(600*Math.exp(-t*20)*t)*Math.exp(-t*2)*0.08}')
JS('    else if(name==="pu"){v=0;for(var h=0;h<3;h++)v+=Math.sin(6.28*(500+h*200)*t)*0.05*Math.exp(-20*Math.abs(t-h*0.07))}')
JS('    else if(name==="alarm"){v=Math.sin(500*t)*Math.sin(6.28*3*t)*0.12}')
JS('    else if(name==="ui"){v=Math.sin(1200*t)*Math.exp(-t*50)*0.06}')
JS('    else if(name==="ohm"){v=Math.sin(120*t)*0.2*Math.exp(-t*6)+n*0.1*Math.exp(-t*4)}')
JS('    else{v=n*0}')
JS('    d[i]=Math.max(-0.5,Math.min(0.5,v))}')
JS('  aBuf[name]=buf;return buf}')
JS('function pS(name,vol){if(!aCtx||mute)return;try{if(!aBuf[name])mkB(name);var s=aCtx.createBufferSource();s.buffer=aBuf[name];var g=aCtx.createGain();g.gain.value=vol||0.3;s.connect(g);g.connect(mG);s.start()}catch(ex){}}')
JS('')

# Particles
JS('var pts=[];')
JS('function sPt(x,y,vx,vy,col,life,sz){if(pts.length>=MP)return;pts.push({x:x,y:y,vx:vx,vy:vy,cl:col,life:life,ml:life,sz:sz||2})}')
JS('function sXB(x,y,cols,n,spd,life,sz){for(var i=0;i<n;i++){var a=Math.random()*6.28,s=Math.random()*spd;sPt(x,y,Math.cos(a)*s,Math.sin(a)*s,cols[i%cols.length],life||0.4+Math.random()*0.4,sz||2)}}')
JS('function uPts(dt){for(var i=pts.length-1;i>=0;i--){var p=pts[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)pts.splice(i,1)}}')
JS('function dPts(cn){var X=cn;for(var i=0;i<pts.length;i++){var p=pts[i],a=Math.max(0,p.life/p.ml);X.globalAlpha=a;X.fillStyle=p.cl;X.shadowColor=p.cl;X.shadowBlur=4;X.beginPath();X.arc(p.x,p.y,p.sz*a,0,6.28);X.fill()}X.globalAlpha=1;X.shadowBlur=0}')
JS('')

# Bullets
JS('var pB=[],eB=[];')
JS('function sPB(x,y,a,spd,dmg,ow,len,w,col){var t=ow==="player"?pB:eB;if(t.length>250)return;t.push({x:x,y:y,a:a,spd:spd,dmg:dmg,ow:ow,len:len||3,w:w||2,col:col||"#fc",life:4,pierce:false,trail:[]})}')
JS('function sEB(x,y,a,spd,dmg,len,w,col,hom,blk){eB.push({x:x,y:y,a:a,spd:spd,dmg:dmg,ow:ow,len:len||3,w:w||2,col:col||"#f88",life:4,pierce:hom,homing:hom,blink:!!blk,trail:[]})}')
JS('function sMN(x,y){for(var i=0;i<3;i++){var a=Math.random()*6.28;eB.push({x:x+Math.cos(a)*20,y:y+Math.sin(a)*20,a:a,spd:0.3,ow:"mine",r:5,life:10,trR:35,col:"#f0f",isMine:true,trail:[]})}}')
JS('function uPB(dt){for(var i=pB.length-1;i>=0;i--){var b=pB[i];b.x+=Math.cos(b.a)*b.spd*dt;b.y+=Math.sin(b.a)*b.spd*dt;b.life-=dt;b.trail.push({x:b.x,y:b.y});if(b.trail.length>6)b.trail.length=6;if(b.x<-30||b.x>CW+30||b.y<-30||b.y>CH+30||b.life<=0)pB.splice(i,1)}')
JS('for(var i=eB.length-1;i>=0;i--){var b=eB[i];if(b.isMine){var fnd=false;for(var j=0;j<enm.length;j++){if(Math.hypot(b.x-enm[j].x,b.y-enm[j].y)<b.trR){fnd=true;break}}if(gBoss&&b.life>7&&Math.hypot(b.x-gBoss.x,b.y-gBoss.y)<b.trR)fnd=true;if(fnd){sXB(b.x,b.y,["#f0f","#fff"],12,4,0.5,3);eB.splice(i,1);continue}b.life-=dt;if(b.life<=0||b.x<-50||b.x>CW+50||b.y<-50||b.y>CH+50)eB.splice(i,1)}')
JS('else if(b.blink){if(cur==="combat"&&pl){var ba=Math.atan2(pl.y-b.y,pl.x-b.x);b.x=pl.x+Math.cos(ba)*50;b.y=pl.y+Math.sin(ba)*50}b.life-=dt;if(b.life<=0)eB.splice(i,1)}')
JS('else if(b.homing&&cur==="combat"&&pl){var dx=pl.x-b.x,dy=pl.y-b.y,ta=Math.atan2(dy,dx),dif=ta-b.a;while(dif>3.14)dif-=6.28;while(dif<-3.14)dif+=6.28;b.a+=dif*Math.min(2.5,dt*6);b.x+=Math.cos(b.a)*b.spd*dt;b.y+=Math.sin(b.a)*b.spd*dt;b.life-=dt;b.trail.push({x:b.x,y:b.y});if(b.trail.length>6)b.trail.length=6;if(b.life<=0||b.x<-50||b.x>CW+50||b.y<-50||b.y>CH+50)eB.splice(i,1)}')
JS('else{b.x+=Math.cos(b.a)*b.spd*dt;b.y+=Math.sin(b.a)*b.spd*dt;b.life-=dt;b.trail.push({x:b.x,y:b.y});if(b.trail.length>6)b.trail.length=6;if(b.life<=0||b.x<-50||b.x>CW+50||b.y<-50||b.y>CH+50)eB.splice(i,1)}}}')
JS('function dPB(cn){var X=cn;X.shadowBlur=5;for(var i=0;i<pB.length;i++){var b=pB[i];X.globalAlpha=Math.min(1,b.life*3);X.strokeStyle=b.col;X.lineWidth=b.w;X.shadowColor=b.col;X.beginPath();X.moveTo(b.x,b.y);X.lineTo(b.x-Math.cos(b.a)*b.len,b.y-Math.sin(b.a)*b.len);X.stroke();X.globalAlpha=0.15;X.lineTo(b.x-Math.cos(b.a)*10,b.y-Math.sin(b.a)*10);X.stroke();X.globalAlpha=1;X.lineWidth=1}')
JS('for(var i=0;i<eB.length;i++){var b=eB[i];if(b.isMine){var pu=0.4+Math.sin(performance.now()/250)*0.3;X.globalAlpha=pu;X.fillStyle=b.col;X.shadowColor=b.col;X.shadowBlur=6;X.beginPath();X.arc(b.x,b.y,b.r,0,6.28);X.fill();X.globalAlpha=pu*0.3;X.strokeStyle=b.col;X.lineWidth=1;X.beginPath();X.arc(b.x,b.y,b.trR,0,6.28);X.stroke();X.globalAlpha=1}else{if(b.blink){X.globalAlpha=0.6;X.fillStyle=b.col;X.shadowColor=b.col;X.shadowBlur=10;X.beginPath();X.arc(b.x,b.y,4,0,6.28);X.fill();X.globalAlpha=1}else{X.globalAlpha=Math.min(1,b.life*2);X.strokeStyle=b.col;X.lineWidth=b.w;X.shadowColor=b.col;X.beginPath();X.moveTo(b.x,b.y);X.lineTo(b.x-Math.cos(b.a)*b.len,b.y-Math.sin(b.a)*b.len);X.stroke();X.globalAlpha=0.15;X.lineTo(b.x-Math.cos(b.a)*10,b.y-Math.sin(b.a)*10);X.stroke();X.globalAlpha=1}}}X.shadowBlur=0;X.globalAlpha=1}')
JS('')

# Power-ups
JS('var puL=[];var PNU=["shield","triple","bubble","nanite","overcharge","mines"],PUC={"shield":"#4f4","triple":"#4ff","bubble":"#ff4","nanite":"#4f8","overcharge":"#f44","mines":"#f4f"},PUL={"shield":"SH","triple":"3X","bubble":"BUB","nanite":"NR","overcharge":"OV","mines":"MN"};')
JS('function sPU(x,y){puL.push({x:x,y:y,ty:PNU[Math.random()*6|0],r:10,life:12})}')
JS('function uPU(dt){for(var i=puL.length-1;i>=0;i--){var p=puL[i];p.life-=dt;if(p.life<=0){puL.splice(i,1);continue}if(cur==="combat"&&pl&&pl.hp>0){if(Math.hypot(pl.x-p.x,pl.y-p.y)<pl.r+p.r+8){aPU(p.ty);puL.splice(i,1)}}}}')
JS('function aPU(type){')
JS('  if(cur!=="combat"||!pl)return;pS("pu",0.3);')
JS('  if(type==="shield")pl.sh=Math.min(pl.sM,pl.sh+30);')
JS('  else if(type==="triple")pw.tri=(pw.tri||0)+15;')
JS('  else if(type==="bubble"){pw.bub=(pw.bub||0)+5;pl.sh=Math.min(pl.sM,pl.sh+30)}')
JS('  else if(type==="nanite")pw.nano=(pw.nano||0)+10;')
JS('  else if(type==="overcharge"){pw.ovc=(pw.ovc||0)+8}')
JS('  else if(type==="mines")pw.minC=(pw.minC||0)+3;')
JS('  sXB(pl.x,pl.y,[PUC[type]||"#fff"],8,3,0.4,2)}')
JS('function dPU(cn){var X=cn;for(var i=0;i<puL.length;i++){var p=puL[i],a=Math.min(1,p.life*2);X.globalAlpha=a;X.fillStyle=PUC[p.ty];X.shadowColor=PUC[p.ty];X.shadowBlur=8;X.beginPath();X.arc(p.x,p.y,p.r+Math.sin(performance.now()/300)*2,0,6.28);X.fill();X.fillStyle="#000";X.font="bold 9px monospace";X.textAlign="center";X.textBaseline="middle";X.fillText(PUL[p.ty],p.x,p.y);X.shadowBlur=0;X.globalAlpha=1}}')
JS('')

# Enemies
JS('var enm=[];var EDEF={scout:{r:10,hp:15,spd:3,col:"#4fc",beh:"scout"},raider:{r:12,hp:30,spd:2.2,col:"#fa2",beh:"raider"},cruiser:{r:18,hp:80,spd:1.2,col:"#f4a",beh:"cruiser"},cannon:{r:14,hp:50,spd:0.6,col:"#8af",beh:"cannon"},swarmling:{r:5,hp:8,spd:2.5,col:"#4f4",beh:"swarmling"},dreadnought:{r:25,hp:150,spd:0.7,col:"#a8a",beh:"dreadnought"}};')
JS('function sEn(tp){if(enm.length>=ME)return;var df=EDEF[tp],s=gs.sec,ep=1+(s-1)*0.08;var sx=Math.random()<0.5?-20:CW+20,sy=100+Math.random()*(CH-200);enm.push({tp:tp,x:sx,y:sy,hp:Math.floor(df.hp*ep),mhp:Math.floor(df.hp*ep),r:df.r,spd:df.spd,col:df.col,beh:df.beh,ft:Math.random()*2,chd:false,chT:0})}')
JS('')
JS('function uEn(dt){for(var i=enm.length-1;i>=0;i--){var e=enm[i];if(cur!=="combat"||!pl)continue;if(e.x<-100||e.x>CW+100||e.y<-100||e.y>CH+100){enm.splice(i,1);continue}')
JS('  e.wb=Math.sin(performance.now()/1000+e.r*3)*0.3;e.ft-=dt;if(e.ft>0&&e.chd)continue;')
JS('  var dx=pl.x-e.x,dy=pl.y-e.y,da=Math.atan2(dy,dx),d=Math.hypot(dx,dy);if(!e.chd)')
JS('  if(e.beh==="scout"){if(d>250){e.x+=(Math.cos(da)+e.wb)*e.spd*60*dt;e.y+=(Math.sin(da)+e.wb)*e.spd*60*dt}else if(d<130){e.x-=Math.cos(da)*e.spd*25*dt;e.y-=Math.sin(da)*e.spd*25*dt}if(e.ft<=0&&d<500){pS("shoot",0.1);sEB(e.x,e.y,da+Math.sin(performance.now()/200)*0.2,e.spd*1.5,5,"enemy",3,1.5,"#4fc");e.ft=1.2}}')
JS('  else if(e.beh==="raider"){if(!e.chd&&d>350){e.x+=Math.cos(da)*e.spd*40*dt;e.y+=(Math.sin(da)+e.wb)*e.spd*40*dt}if(!e.chd&&d<=350){e.chd=true;e.chT=1.5;e.ft=2}if(e.chd){e.chT-=dt;if(e.chT>0){e.x+=(Math.cos(da)+e.wb)*e.spd*80*dt;e.y+=(Math.sin(da)+e.wb)*e.spd*80*dt}else if(e.chT>-0.3){var ba=Math.atan2(pl.y-e.y,pl.x-e.x);pS("shoot",0.15);for(var k=-1;k<=1;k+=2)sEB(e.x,e.y,ba+k*0.15,3,8,"enemy",3,2,"#fa2")}else{e.chd=false;e.chT=-8;e.ft=2}}}')
JS('  else if(e.beh==="cruiser"){if(d>300){e.x+=(Math.cos(da)+e.wb)*e.spd*30*dt;e.y+=(Math.sin(da)+e.wb)*e.spd*30*dt}if(d<200){e.x-=(Math.cos(da)+e.wb)*e.spd*25*dt;e.y-=(Math.sin(da)+e.wb)*e.spd*25*dt}if(e.ft<=0){pS("boom",0.08);for(var j=0;j<3;j++){sEB(e.x,e.y,da-0.1+j*0.1,e.spd*1.3,7,"enemy",4,2,"#f4a")}e.ft=2.5}}')
