JS('function dEn(cn){var X=cn;for(var i=0;i<enm.length;i++){var e=enm[i];X.save();X.translate(e.x,e.y);X.fillStyle=e.col;X.shadowColor=e.col;X.shadowBlur=6;if(e.beh==="scout"){X.beginPath();X.moveTo(0,-e.r);X.lineTo(e.r,e.r*0.5);X.lineTo(-e.r,e.r*0.5);X.closePath();X.fill()}else if(e.beh==="raider"){X.beginPath();X.moveTo(0,-e.r);X.lineTo(e.r*0.7,e.r*0.7);X.lineTo(-e.r*0.7,e.r*0.7);X.closePath();X.fill()}else if(e.beh==="cruiser"){for(var j=0;j<6;j++){var a=j*Math.PI/3-Math.PI/6;X.beginPath();X.moveTo(0,0);X.lineTo(Math.cos(a)*e.r,Math.sin(a)*e.r);X.lineTo(Math.cos(a+0.52)*e.r,Math.sin(a+0.52)*e.r);X.closePath();X.fill()}X.fillStyle="#000";X.beginPath();X.arc(0,0,e.r*0.4,0,6.28);X.fill()}else if(e.beh==="cannon"){X.fillRect(-e.r,-e.r*0.7,e.r*2,e.r*1.4);var ca=Math.atan2(pl?pl.y-e.y:0,pl?pl.x-e.x:0);X.save();X.rotate(ca);X.fillRect(e.r*0.3,-e.r*0.15,e.r*0.8,e.r*0.3);X.restore()}else{X.beginPath();X.arc(0,0,e.r,0,6.28);X.fill()}X.shadowBlur=0;X.fillStyle="#000";X.fillRect(-e.r,-e.r-8,e.r*2,4);X.fillStyle=e.col;X.fillRect(-e.r,-e.r-8,(e.r*2)*(Math.max(0,e.hp)/e.mhp),4);X.restore()}}')
