JS('function uBo(dt){if(!gBoss||gBoss.hp<=0)return;var b=gBoss;if(b.y<100)b.y+=1.0;b.x+=Math.sin(performance.now()/3000)*2;b.x=Math.max(b.r,Math.min(CW-b.r,b.x));b.ft-=dt;b.st-=dt;var m=b.p===3?0.6:1.0')
