JS('  if(b.tp===1&&b.p>=1&&b.st<=0){b.st=(5+Math.random()*3)/m;for(var j=0;j<3;j++){sEn("swarmling",b.x+Math.random()*100-50,b.y+40)}}')
JS('  if(b.tp===1&&b.p>=2&&b.st<=0){b.st=4/m;sXB(b.x,b.y,["#fff","#f0f"],10,5,0.3)}')
JS('  if(b.tp===2&&b.st<=0){b.st=(2+Math.random())/m;for(var k=-3;k<=3;k++){sEB(b.x,b.y,ba+k*0.15,2.5,8,"bossBul",3,2,"#f80",true)}}')
JS('  if(b.tp===2&&b.p>=2&&b.ft<=0){b.ft=2/m;sEB(b.x,b.y,ba,4,25,"bossBul",20,4,"#fff",false,true)}')
JS('  if(b.tp===3&&b.st<=0){b.st=4/m;for(var j=0;j<4;j++){sEB(b.x,b.y,ba+j*0.2,b.spd*2,7,"bossBul",3,2,"#4ef")}}')
JS('  if(b.tp===3&&b.st<=2){b.st=6/m;for(var i=0;i<2;i++){var zr=60+Math.random()*40,zA=Math.random()*6.28;gs.zones.push({x:b.x+Math.cos(zA)*zr,y:b.y+Math.sin(zA)*zr,r:zr,life:8,dmg:10})}}')
