JS('function dBo(cn){if(!gBoss||gBoss.hp<=0)return;var X=cn,b=gBoss;X.save();X.translate(b.x,b.y);X.fillStyle="#888";X.shadowColor=b.tp===1?"#f0f":b.tp===2?"#fa0":"#0ef";X.shadowBlur=10;if(b.tp===1){X.beginPath();X.moveTo(0,-b.r);X.lineTo(b.r,b.r*0.5);X.lineTo(b.r*0.3,b.r);X.lineTo(-b.r*0.3,b.r);X.lineTo(-b.r,b.r*0.5);X.closePath();X.fill();X.fillStyle="#f0f";X.shadowBlur=15;X.beginPath();X.arc(-b.r*0.2,-b.r*0.1,b.r*0.2,0,6.28);X.fill();X.beginPath();X.arc(b.r*0.2,-b.r*0.1,b.r*0.2,0,6.28);X.fill()}else if(b.tp===2){X.fillRect(-b.r,-b.r*0.6,b.r*2,b.r*1.2);X.fillStyle="#fff";X.fillRect(-b.r*0.7,-b.r*0.3,b.r*1.4,b.r*0.6);X.fillStyle="#f00";X.beginPath();X.arc(-b.r*0.4,-b.r*0.4,b.r*0.15,0,6.28);X.fill();X.beginPath();X.arc(b.r*0.4,-b.r*0.4,b.r*0.15,0,6.28);X.fill()}else{X.fillStyle="#0ef";X.shadowBlur=12;X.beginPath();X.moveTo(0,-b.r);X.lineTo(b.r*0.8,b.r*0.3);X.lineTo(b.r*0.4,b.r);X.lineTo(-b.r*0.4,b.r);X.lineTo(-b.r*0.8,b.r*0.3);X.closePath();X.fill();X.fillStyle="#f0f";for(var i=0;i<6;i++){var a=i*Math.PI/3;X.beginPath();X.arc(Math.cos(a)*b.r*0.6,Math.sin(a)*b.r*0.6,b.r*0.1,0,6.28);X.fill()}}X.shadowBlur=0;X.fillStyle="#000";X.fillRect(-b.r,-b.r-30,b.r*2,6);X.fillStyle="#0f0";X.fillRect(-b.r,-b.r-30,(b.r*2)*(Math.max(0,b.hp)/b.mhp),6);X.fillStyle="#f0f";X.font="bold 12px monospace";X.textAlign="center";X.textBaseline="bottom";X.fillText(b.tp===1?"Reaver Queen":b.tp===2?"Iron Monarch":"Leviathan",0,-b.r-33);X.restore()}')
