JS('  if(gBoss&&gBoss.hp>0){for(var i=pB.length-1;i>=0;i--){var b=pB[i];if(Math.hypot(b.x-gBoss.x,b.y-gBoss.y)>gBoss.r+5)continue;var d2=b.dmg*(MT.wDmg>0?1+MT.wDmg*0.05:1);if(MT.crit&&Math.random()<0.1)d2*=2;gBoss.hp-=d2;pS("hit",0.12);sXB(b.x,b.y,["#f0f"],3,2,0.2,1.5);if(gBoss.hp<=0){kGB(gBoss);gBoss=null}pB.splice(i,1)}}')
JS('  for(var i=eB.length-1;i>=0;i--){var eb=eB[i];if(!eb.isMine)continue;for(var j=enm.length-1;j>=0;j--){var e=enm[j];if(Math.hypot(eb.x-e.x,eb.y-e.y)>eb.trR)continue;e.hp-=50;sXB(e.x,e.y,["#f0f","#fff"],15,4,0.5,3);if(e.hp<=0)enm.splice(j,1);eB.splice(i,1);break}}}')
JS('function kE(e,idx){var pts=SCR[e.eph]||40;gs.score+=pts;cT=CCW;cK++;var ml=Math.min(CXM,1+CBL*(cK-1));gs.score+=(pts*ml)|0;pS("boom",0.25);sXB(e.x,e.y,[e.col,"#fff","#aaa"],Math.max(8,Math.floor(e.r)*2),e.r,0.5+Math.random()*0.3,e.r*0.15);gs.shk=Math.max(gs.shk,e.r*0.15);var cr=0;if(e.beh==="raider")cr=12;else if(e.beh==="cruiser")cr=15;else if(e.beh==="dreadnought")cr=25+Math.floor(Math.random()*10);else if(e.beh==="cannon")cr=12;else cr=4+Math.floor(Math.random()*8);gs.credits+=cr;if(e.beh==="raider"||e.beh==="cruiser"||e.beh==="dreadnought")if(Math.random()<0.25)sPU(e.x,e.y);if(e.beh==="dreadnought")sMN(e.x,e.y)}')
JS('function kGB(b){gs.score+=SCR.boss;pS("boom",0.5);sXB(b.x,b.y,["#f0f","#f4f","#fa0","#fff"],40,5,0.8,3);gs.shk=15;MT.starCharts+=10;secCl=Math.max(secCl||0,gs.sec);saveSV()}')
