JS('/* WAVES */')
JS('var wbudget=0,wspawned=0,wtimer=2;')
JS('function calcWB(){return 18+gs.sec*6}')
JS('function uWB(dt){')
JS('  if(wspawned>=wbudget)return;wtimer-=dt;if(wtimer>0)return;')
JS('  if(wbudget<=0){wbudget=calcWB();wspawned=0;wtimer=0;return}')
JS('  var s=gs.sec,pl=[];if(s===1)pl=["scout","scout","swarmling"];else if(s===2)pl=["scout","swarmling","raider"];else if(s===3)pl=["raider","cruiser","cruiser","swarmling"];else if(s===4)pl=["raider","cruiser","cannon","swarmling"];else if(s===5)pl=["cruiser","cannon","dreadnought","raider"];else if(s===6)pl=["dreadnought","cruiser","cannon","cannon"];else pl=["dreadnought","dreadnought","cannon","cruiser","raider","swarmling"];')
JS('  var cnt=1+Math.floor(Math.random()*3);')
JS('  for(var i=0;i<cnt&&wspawned<wbudget;i++){')
JS('    var tp=pl[Math.random()*pl.length|0];')
JS('    if(tp==="swarmling"){for(var k=0;k<5+s;k++){sEn("swarmling")}wspawned++}')
JS('    else{sEn(tp);wspawned++}}')
JS('  wtimer=0.4;')
JS('  if(wspawned>=wbudget&&enm.length===0&&gBoss===null){')
JS('    wbudget=0;wspawned=0;wtimer=2;')
JS('    if(s%3===0&&!gBoss){gBoss=mkBo(s);pS("alarm",0.5)}')
JS('    else{')
JS('      gs.sec++;')
