JS('  if(pl.dsh||Math.abs(pl.vx)+Math.abs(pl.vy)>0.5){var ang=Math.atan2(pl.vy,pl.vx);sPt(pl.x-Math.cos(ang)*pl.r,pl.y-Math.sin(ang)*pl.r,-Math.cos(ang)*2+Math.random()*0.5,-Math.sin(ang)*2+Math.random()*0.5,"#4af",0.2,3)}}')
