# Player update
JS('/* PLAYER UPDATE */')
JS('function uPl(dt){')
JS('  if(!pl||cur!=="combat")return;')
JS('  var mx=0,my=0;')
JS('  if(iK[65]||iK[37])mx--;if(iK[68]||iK[39])mx++;if(iK[87]||iK[38])my--;if(iK[83]||iK[40])my++;')
JS('  if(mx||my){var l=Math.sqrt(mx*mx+my*my);mx/=l;my/=l}')
JS('  var spd=pl.spd*(MT.engineLv>0?1+MT.engineLv*0.08:1);if(MT.speed)spd*=1.25;')
JS('  if(!pl.dsh){pl.vx=mx*spd;pl.vy=my*spd;pl.x+=pl.vx*dt;pl.y+=pl.vy*dt}')
JS('  pl.x=Math.max(pl.r,Math.min(CW-pl.r,pl.x));pl.y=Math.max(pl.r,Math.min(CH-pl.r,pl.y));')
JS('  if(pl.dsh){pl.dT-=dt;if(pl.dT<=0){pl.dsh=false;pl.dCD=1};pl.x+=Math.cos(iA)*pl.dSp*60*dt;pl.y+=Math.sin(iA)*pl.dSp*60*dt;pl.x=Math.max(pl.r,Math.min(CW-pl.r,pl.x));pl.y=Math.max(pl.r,Math.min(CH-pl.r,pl.y));sPt(pl.x-Math.cos(iA)*pl.r,pl.y-Math.sin(iA)*pl.r,-Math.cos(iA)*2,-Math.sin(iA)*2,"#4af",0.25,3)}')
JS('  pl.dCD=Math.max(0,pl.dCD-dt);if(iK[32]&&pl.dCD<=0&&!pl.dsh){pl.dsh=true;pl.dt=0.15;pl.dCD=1;pS("dash",0.3)}')
JS('  var firing=iK[229]||iK[13]||iM.dn;')
JS('  if(firing&&cur==="combat"&&!pl.oh){')
JS('    var fr=Math.max(0.4,4-MT.mainLv*1.8);if(pw.triple>0)fr=Math.min(fr,0.5);')
JS('    if(pl.frT<=0){pl.frT=fr;if(pw.triple>0)fr=Math.min(fr,0.5);')
JS('      var dmg=12,hAmt=8;')
JS('      if(MT.mainLv>=1){dmg=30;hAmt=13}else if(MT.mainLv>=2){dmg=22;hAmt=11}')
JS('      if(MT.rail&&MT.spreadLv>0){dmg=70;hAmt=25;fr=0.8}')
JS('      if(pw.overcharge>0)hAmt=0;if(MT.heatLv>0)hAmt*=Math.max(0.2,1-MT.heatLv*0.3);')
JS('      var sc=1;if(pw.triple>0)sc=3;if(MT.spreadLv>0&&MT.mainLv>=1)sc+=2;')
JS('      for(var i=0;i<sc;i++){var sp=sc>1?((i-(sc-1)/2)*0.15):0;var cl="#fc";if(MT.mainLv>=2)cl="#fa0";sPB(pl.x+Math.cos(iA)*pl.r,pl.y+Math.sin(iA)*pl.r,iA+sp,8,dmg,"player",MT.mainLv>=2?4:3,MT.mainLv>=2?3:2,cl)}')
JS('      pl.h+=hAmt;pS("shoot",0.12)}}')
JS('  if(pl.h>=HM){pl.oh=true;pl.ohT=1.5;pS("ohm",0.3)}')
JS('  pl.ohT-=dt;if(pl.ohT<=0){pl.oh=false}pl.h=Math.max(0,pl.h-pl.hd*dt);')
JS('  if(pw.overcharge>0){pw.overcharge-=dt;pl.h=Math.max(0,pl.h)}')
JS('  pl.sr-=dt;if(pl.sr<=0){var regAmt=Math.max(0,pl.sM-pl.sh)*0.01*(1+MT.shieldRlv*0.5);pl.sh+=regAmt;if(pl.sh>=pl.sM)pl.sh=pl.sM;pl.sr=3/(1+MT.shieldRlv*0.5)}')
JS('  if(pl.rT<=0&&pl.hp<pl.mhp&&MT.repairLv>0){pl.hp=pl.hp+Math.min(1e-6,pl.mhp-pl.hp)*MT.repairLv*dt;pl.rT=2}')
JS('  if(pw.triple>0)pw.triple-=dt;if(pw.bubble>0){pw.bubble-=dt;pl.sh=Math.min(pl.sM,pl.sh+30)};if(pw.nanite>0)pw.nano=Math.max(0,pw.nano-dt);if(pw.nano>0&&pl.hp<pl.mhp)pl.hp+=2*dt;if(pw.nano>0)pw.nano-=dt;if(pw.overcharge>0)pw.overcharge-=dt;')
JS('  if(pw.mineCount>0&&pl.h<3){for(var i=0;i<pw.mineCount;i++){var pa=Math.random()*6.28;sMN(pl.x+Math.cos(pa)*10,pl.y+Math.sin(pa)*10)}pw.mineCount=0}')
JS('  if(pl.hp<=0){pl.hp=0;pS("boom",0.5);sXB(pl.x,pl.y,["#f44","#fa0","#fff","#ff4"],20,5,0.8,3);gs.shk=20;MT.starCharts+=Math.floor(gs.sec*0.5)+10;secCl=Math.max(secCl||0,gs.sec);saveSV();addSc(gs.score,gs.sec);cur="gameOver"}')
JS('  if(cT>0){cT-=dt;if(cT<=0)cK=0}')
JS('}')
